package com.chickencenter.ui.controllers;import javafx.application.Platform;public class NavigationHelper {    private static Runnable navigationCallback = null;    private static String navigateTo = null;    public static void setNavigationCallback(Runnable callback) {        navigationCallback = callback;    }    public static void navigateTo(String view) {        navigateTo = view;        if (navigationCallback != null) {            Platform.runLater(navigationCallback);        }    }    public static String getNavigateTo() {        return navigateTo;    }    public static void clearNavigateTo() {        navigateTo = null;    }}
